/**
 * The client's opening frame.
 */
export const Hello = Schema.Struct({
  schema: B3Hash,
  token: Schema.optional(Schema.NullOr(Schema.String)),
  wire_v: Schema.Int,
}).annotate({ identifier: "Hello" });
export type Hello = typeof Hello.Type;

/**
 * Whether this session counts as somebody watching the monitor.
 */
export const Monitoring = Schema.Union([
  Schema.Literal("release"),
  Schema.Literal("watch"),
  Schema.Literal("watch_summary"),
]).annotate({ identifier: "Monitoring" });
export type Monitoring = typeof Monitoring.Type;

/**
 * Everything a client may send.
 */
export const ClientFrame = Schema.Union([
  Schema.Struct({
    hello: Hello,
  }),
  Schema.Struct({
    command: Command,
  }),
  Schema.Struct({
    ask: Ask,
  }),
  Schema.Struct({
    monitor: Monitoring,
  }),
]).annotate({ identifier: "ClientFrame" });
export type ClientFrame = typeof ClientFrame.Type;

/**
 * One piece of what a model is producing, before the call it belongs to
 * has settled.
 * 
 * **Reasoning and prose are two streams, not one.** A model that spends
 * most of a call reasoning sends almost nothing on the prose stream,
 * and a page that appended both to one buffer would either show a
 * person their own model's scratch work as its answer or show them an
 * empty thread for three minutes. Which stream a piece came from is
 * therefore part of the piece, and no reader has to guess.
 */
export const Increment = Schema.Union([
  Schema.Struct({
    said: Schema.String,
  }),
  Schema.Struct({
    thought: Schema.String,
  }),
]).annotate({ identifier: "Increment" });
export type Increment = typeof Increment.Type;

/**
 * One piece of what a model is producing, on its way to a page.
 * 
 * The piece says which of the two streams it came from, because a page
 * draws them differently: prose is the answer and reasoning is folded
 * away beside it.
 */
export const Delta = Schema.Struct({
  increment: Increment,
  run: RunId,
}).annotate({ identifier: "Delta" });
export type Delta = typeof Delta.Type;

/**
 * Ledger records that never reached a peer, named by both ends.
 * 
 * Both ends come from records this session can name, never from the
 * count a lagged subscription reports: that count says how many
 * messages were skipped and neither endpoint, so a reader holding it
 * cannot ask for the range it lost. `from` is the record after the last
 * one the session delivered; `to` is the record before the first one to
 * arrive after the gap.
 */
export const Lagged = Schema.Struct({
  from: Seq,
  to: Seq,
}).annotate({ identifier: "Lagged" });
export type Lagged = typeof Lagged.Type;

/**
 * Which of a command's two outputs a piece came from.
 */
export const OutputStream = Schema.Literals(["out", "err"]).annotate({ identifier: "OutputStream" });
export type OutputStream = typeof OutputStream.Type;

/**
 * One piece of a running command's output, on its way to a page.
 * 
 * `text` is decoded lossily: a piece ends at a byte bound, which can
 * fall inside a character, and the settled result is what a page keeps.
 */
export const LiveOutput = Schema.Struct({
  run: RunId,
  stream: OutputStream,
  text: Schema.String,
}).annotate({ identifier: "LiveOutput" });
export type LiveOutput = typeof LiveOutput.Type;

/**
 * Who reads a log line, and when.
 * 
 * The five `docs/logging.md` names, spelled on the wire exactly as
 * `runtime::diagnostics::Level` spells them on a terminal. This crate
 * cannot depend on `runtime` — the graph points inward — so the
 * mapping between the two lives at the assembly layer, where a test
 * holds the two spellings equal name for name.
 */
export const LogLevel = Schema.Literals(["refuse", "effect", "decide", "trace", "wire"]).annotate({ identifier: "LogLevel" });
export type LogLevel = typeof LogLevel.Type;

/**
 * One diagnostic line on its way to a page.
 */
export const LogLine = Schema.Struct({
  level: LogLevel,
  line: Schema.String,
  module: Schema.String,
  run: Schema.optional(Schema.NullOr(RunId)),
  seq: Seq,
  t: Schema.optional(Schema.NullOr(TimeMs)),
}).annotate({ identifier: "LogLine" });
export type LogLine = typeof LogLine.Type;

/**
 * One reading of every counter the monitor shows, in integers because
 * it travels on the wire (`crates/sprawling/Spec.lean` §8-94, §8-129-6).
 */
export const Sample = Schema.Struct({
  core_cpu_permille: Schema.Int,
  core_private_bytes: Schema.Int,
  core_read_bytes: Schema.Int,
  core_working_set_bytes: Schema.Int,
  core_written_bytes: Schema.Int,
  durable_lag: Schema.Int,
  event_to_screen_p50_nanos: Schema.Int,
  ledger_queue_depth: Schema.Int,
  machine_available_bytes: Schema.Int,
  machine_cpu_permille: Schema.Int,
  queued_runs: Schema.Int,
  read_nanos: Schema.Int,
  relay_p50_nanos: Schema.Int,
  view_backlog: Schema.Int,
  volume_free_bytes: Schema.Int,
}).annotate({ identifier: "Sample" });
export type Sample = typeof Sample.Type;

/**
 * The server's answer to a `Hello` it accepted.
 */
export const Welcome = Schema.Struct({
  city: Schema.optional(Schema.NullOr(Address)),
  epoch: Schema.optional(Schema.NullOr(B3Hash)),
  resume_from: Schema.optional(Schema.NullOr(Seq)),
  schema: B3Hash,
  wire_v: Schema.Int,
}).annotate({ identifier: "Welcome" });
export type Welcome = typeof Welcome.Type;

/**
 * Everything a server may send. Events are the push half; a `Refusal`
 * carries the three-part refusal the interface renders verbatim.
 * 
 * **`Delta` is deliberately not an event.** An event is a thing that
 * happened, and a token increment is not: it has no sequence number, it
 * is never written to the Ledger, it cannot be replayed, and a client
 * that missed one has lost nothing. Giving it a frame class of its own
 * is what keeps that true — folded into the event stream it would
 * become a second, unverifiable history of what the model said.
 */
export const ServerFrame = Schema.Union([
  Schema.Struct({
    welcome: Welcome,
  }),
  Schema.Struct({
    event: EventRecord,
  }),
  Schema.Struct({
    answered: Answered,
  }),
  Schema.Struct({
    refusal: AxError,
  }),
  Schema.Struct({
    delta: Delta,
  }),
  Schema.Struct({
    log: LogLine,
  }),
  Schema.Struct({
    lagged: Lagged,
  }),
  Schema.Struct({
    output: LiveOutput,
  }),
  Schema.Struct({
    monitor: Sample,
  }),
]).annotate({ identifier: "ServerFrame" });
export type ServerFrame = typeof ServerFrame.Type;

